import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';
import { linear } from "svelte/easing";
import { fly } from "svelte/transition";
import { TaskTypeEnum } from "$lib/utils/enums/task.enum";
import { taskStore as store } from "$lib/stores/task.store";
import Uploader from "$lib/components/Uploader.svelte";
import LocationAutoComplete from "$lib/components/LocationAutoComplete.svelte";
import { t, locale } from "svelte-i18n";

var on_click = (_, $store) => $.store_mutate(store, $.untrack($store).isRemovals = true, $.untrack($store));
var root_2 = $.template(`<span class="label-text-alt text-error block"> </span>`);
var root_1 = $.template(`<div class="w-full"><!></div> <div class="w-full"><!></div> <!>`, 1);
var root_5 = $.template(`<span class="label-text-alt text-error"> </span>`);
var root_4 = $.template(`<div class="w-full"><!> <!></div>`);
var root_3 = $.template(`<p class="text-lg font-semibold"> </p> <div class="flex gap-4"><button> </button> <button> </button></div> <!>`, 1);
var root = $.template(`<div class="space-y-4"><h3 class="text-lg font-semibold"> </h3> <div class="flex gap-4"><button> </button> <button> </button></div> <div class="h-1"></div> <!> <div class="w-full"><div class="my-5"><label for="attachments" class="label block text-lg font-semibold text-white"> </label> <label for="attachments" class="label-text-alt block text-white/70"> </label></div> <!></div></div>`);

export default function TaskLocation($$anchor, $$props) {
	$.push($$props, true);

	const [$$stores, $$cleanup] = $.setup_stores();
	const $store = () => $.store_get(store, '$store', $$stores);
	const $t = () => $.store_get(t, '$t', $$stores);
	let newFiles = $.prop($$props, 'newFiles', 15);

	const handleFileUpload = async (files) => {
		if (!files || files.length === 0 || files.length > 5) return;

		const savedAttachmentsCount = $store().task.attachments?.length || 0;

		newFiles(files.slice(savedAttachmentsCount).filter((file) => file instanceof File));
	};

	const handleFileRemove = (index, file) => {
		const savedAttachmentsCount = $store().task.attachments?.length || 0;

		if (index < savedAttachmentsCount) {
			const attachment = $store().task.attachments?.[index];

			if (attachment) {
				$$props.attachmentsToRemove.push(attachment);
				$store().task.attachments?.splice(index, 1);
			}
		}
	};

	let uploaderFiles = $.derived(() => (() => {
		const savedAttachments = $store().task.attachments?.map((file) => file.url) || [];

		return [...savedAttachments, ...newFiles()];
	})());

	var div = root();
	var h3 = $.child(div);
	var text = $.child(h3, true);

	$.reset(h3);

	var div_1 = $.sibling(h3, 2);
	var button = $.child(div_1);

	button.__click = [on_click, $store];

	var text_1 = $.child(button, true);

	$.reset(button);

	var button_1 = $.sibling(button, 2);

	button_1.__click = () => {
		$.store_mutate(store, $.untrack($store).isRemovals = false, $.untrack($store));

		store.updateTask({
			dropOffLocation: {
				displayName: '',
				longitude: null,
				latitude: null,
				zipCode: '',
				locationLoaded: false
			}
		});
	};

	var text_2 = $.child(button_1, true);

	$.reset(button_1);
	$.reset(div_1);

	var node = $.sibling(div_1, 4);

	{
		var consequent_1 = ($$anchor) => {
			var fragment = root_1();
			var div_2 = $.first_child(fragment);
			var node_1 = $.child(div_2);
			const expression = $.derived(() => $t()('task.pickup_location'));
			const expression_1 = $.derived(() => $t()('task.address_placeholder'));

			LocationAutoComplete(node_1, {
				get label() {
					return $.get(expression);
				},
				get placeholder() {
					return $.get(expression_1);
				},
				get location() {
					return $store().task.pickupLocation;
				},
				onLocationSelect: (location) => {
					store.updateTask({
						pickupLocation: { ...location, locationLoaded: true }
					});
				}
			});

			$.reset(div_2);

			var div_3 = $.sibling(div_2, 2);
			var node_2 = $.child(div_3);
			const expression_2 = $.derived(() => $t()('task.dropoff_location'));
			const expression_3 = $.derived(() => $t()('task.address_placeholder'));

			LocationAutoComplete(node_2, {
				get label() {
					return $.get(expression_2);
				},
				get placeholder() {
					return $.get(expression_3);
				},
				get location() {
					return $store().task.dropOffLocation;
				},
				onLocationSelect: (location) => {
					store.updateTask({
						dropOffLocation: { ...location, locationLoaded: true }
					});
				}
			});

			$.reset(div_3);

			var node_3 = $.sibling(div_3, 2);

			{
				var consequent = ($$anchor) => {
					var span = root_2();
					var text_3 = $.child(span, true);

					$.reset(span);
					$.template_effect(() => $.set_text(text_3, $$props.errors.location));
					$.append($$anchor, span);
				};

				$.if(node_3, ($$render) => {
					if ($$props.errors.location) $$render(consequent);
				});
			}

			$.append($$anchor, fragment);
		};

		var alternate = ($$anchor) => {
			var fragment_1 = root_3();
			var p = $.first_child(fragment_1);
			var text_4 = $.child(p, true);

			$.reset(p);

			var div_4 = $.sibling(p, 2);
			var button_2 = $.child(div_4);

			button_2.__click = () => store.updateTask({ taskType: TaskTypeEnum.IN_PERSON });

			var text_5 = $.child(button_2, true);

			$.reset(button_2);

			var button_3 = $.sibling(button_2, 2);

			button_3.__click = () => {
				const defaultLocation = {
					displayName: '',
					longitude: null,
					latitude: null,
					zipCode: '',
					locationLoaded: false
				};

				store.updateTask({
					taskType: TaskTypeEnum.REMOTE,
					pickupLocation: defaultLocation,
					dropOffLocation: defaultLocation
				});
			};

			var text_6 = $.child(button_3, true);

			$.reset(button_3);
			$.reset(div_4);

			var node_4 = $.sibling(div_4, 2);

			{
				var consequent_3 = ($$anchor) => {
					var div_5 = root_4();
					var node_5 = $.child(div_5);
					const expression_4 = $.derived(() => $t()('task.location'));
					const expression_5 = $.derived(() => $t()('task.address_placeholder'));

					LocationAutoComplete(node_5, {
						get label() {
							return $.get(expression_4);
						},
						get placeholder() {
							return $.get(expression_5);
						},
						get location() {
							return $store().task.pickupLocation;
						},
						onLocationSelect: (location) => {
							store.updateTask({
								pickupLocation: { ...location, locationLoaded: true }
							});
						}
					});

					var node_6 = $.sibling(node_5, 2);

					{
						var consequent_2 = ($$anchor) => {
							var span_1 = root_5();
							var text_7 = $.child(span_1, true);

							$.reset(span_1);
							$.template_effect(() => $.set_text(text_7, $$props.errors.location));
							$.append($$anchor, span_1);
						};

						$.if(node_6, ($$render) => {
							if ($$props.errors.location) $$render(consequent_2);
						});
					}

					$.reset(div_5);
					$.append($$anchor, div_5);
				};

				$.if(node_4, ($$render) => {
					if ($store().task?.taskType === TaskTypeEnum.IN_PERSON) $$render(consequent_3);
				});
			}

			$.template_effect(
				($0, $1, $2) => {
					$.set_text(text_4, $0);
					$.set_class(button_2, 1, `btn ${$store().task?.taskType === TaskTypeEnum.IN_PERSON ? 'btn-primary' : 'btn-outline'}`);
					$.set_text(text_5, $1);
					$.set_class(button_3, 1, `btn ${$store().task?.taskType === TaskTypeEnum.REMOTE ? 'btn-primary' : 'btn-outline'}`);
					$.set_text(text_6, $2);
				},
				[
					() => $t()('task.location_question'),
					() => $t()('task.in_person'),
					() => $t()('task.remote')
				]
			);

			$.append($$anchor, fragment_1);
		};

		$.if(node, ($$render) => {
			if ($store().isRemovals) $$render(consequent_1); else $$render(alternate, false);
		});
	}

	var div_6 = $.sibling(node, 2);
	var div_7 = $.child(div_6);
	var label = $.child(div_7);
	var text_8 = $.child(label, true);

	$.reset(label);

	var label_1 = $.sibling(label, 2);
	var text_9 = $.child(label_1, true);

	$.reset(label_1);
	$.reset(div_7);

	var node_7 = $.sibling(div_7, 2);
	const expression_6 = $.derived(() => $t()('task.attachments'));

	Uploader(node_7, {
		id: 'attachments',
		get label() {
			return $.get(expression_6);
		},
		allowedTypes: ['image/*', 'video/*'],
		get files() {
			return $.get(uploaderFiles);
		},
		maxFiles: 5,
		maxFileSize: 100,
		maxDuration: 30,
		className: 'w-full h-full min-h-28',
		onChange: handleFileUpload,
		onRemove: handleFileRemove
	});

	$.reset(div_6);
	$.reset(div);

	$.template_effect(
		($0, $1, $2, $3, $4) => {
			$.set_text(text, $0);
			$.set_class(button, 1, `btn min-w-1/3 text-xl ${$store().isRemovals ? 'btn-primary' : 'btn-outline'}`);
			$.set_text(text_1, $1);
			$.set_class(button_1, 1, `btn min-w-1/3 text-xl ${!$store().isRemovals ? 'btn-primary' : 'btn-outline'}`);
			$.set_text(text_2, $2);
			$.set_text(text_8, $3);
			$.set_text(text_9, $4);
		},
		[
			() => $t()('task.relocation_question'),
			() => $t()('task.yes'),
			() => $t()('task.no'),
			() => $t()('task.attachments_label'),
			() => $t()('task.attachments_hint')
		]
	);

	$.transition(1, div, () => fly, () => ({
		duration: 200,
		easing: linear,
		y: 0,
		x: $$props.direction === 'forward' ? 20 : -20
	}));

	$.append($$anchor, div);
	$.pop();
	$$cleanup();
}

$.delegate(['click']);
